import{z as l,x as n,o as c,c as p,q as a,j as s,D as o,d as E,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"套接字层的实现","description":"","frontmatter":{"title":"套接字层的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/npk-socket-layer.md","filePath":"cs/npk-socket-layer.md","lastUpdated":1791063341000}'),B={name:"cs/npk-socket-layer.md"};function i(f,e,A,k,_,m){const d=n("Mermaid");return c(),p("div",null,[e[2]||(e[2]=a('<h1 id="套接字层的实现" tabindex="-1">套接字层的实现 <a class="header-anchor" href="#套接字层的实现" aria-label="Permalink to &quot;套接字层的实现&quot;">​</a></h1><div class="epigraph"><p>进程手里捏着的只是文件描述符表里的一项；把它变成一条 TCP 连接的，是 fd、BSD 套接字、协议 sock 三层对象之间一张固定的映射表。</p><footer>—— 据 Leffler 等, <em>The Design and Implementation of the 4.3BSD UNIX Operating System</em>；Stevens, <em>UNIX Network Programming</em> 整理</footer></div><p><a href="/cs/npk-congestion-implementation">上一课</a>结束时，TCP 的全部收发状态——状态机、拥塞变量、重传队列——都挂在协议层的 sock 对象上；但应用从来碰不到 sock，它手里只有 <code>socket()</code> 返回的一个整数。主干课用<a href="/cs/socket-api">套接字 API</a> 钉过调用形状，用<a href="/cs/socket-buffers">缓冲与背压</a>钉过内存会计，<a href="/cs/socket-options">套接字选项</a>列过旋钮，<a href="/cs/hpc-epoll-deep">hpc-epoll 深化</a>拆过事件循环。本课补最后一层实现：fd 到 sock 的三层映射怎么查、<code>read</code> 与 <code>poll</code> 怎么落到同一条等待队列、连接的身份与生命周期归谁管。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三层对象不是故弄玄虚，每层各答一个问题：fd 答进程局部性（同一 sock 可以被多个 fd、多个进程指着）；BSD 套接字（<code>struct socket</code>）答协议族无关（<code>AF_INET</code> 与 <code>AF_UNIX</code> 在这一层调用形状相同）；协议 sock（<code>struct sock</code>）答协议状态。不这么做会错在哪：把 fd 当连接本身，就会在 <code>fork</code> 或 <code>dup</code> 之后误判——两个 fd 指同一个 sock，只 close 其中一个，连接照活，TIME_WAIT 与发送照常进行；以为 <code>accept()</code> 那一刻连接才建立，会在 accept 队列堆积时误把「完成握手但没被领走」的连接当不存在——它们早就占着内核资源；在非阻塞监听 fd 上不处理 accept 的 EAGAIN，事件循环会被假唤醒打转。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>顺着一次 <code>read()</code> 走。fd 经进程文件表找到 file，file 的操作表指向 sockfs 的统一入口 <code>sock_read_iter</code>，它调 BSD 层的 <code>inet_recvmsg</code>，再按协议派给 <code>tcp_recvmsg</code> 或 <code>udp_recvmsg</code>——三层各转发一次，协议语义只在最底层分岔。等待与唤醒：阻塞读把当前进程挂到 sock 的等待队列上睡；<a href="/cs/npk-rx-path">收包路径</a>末端那个 <code>sk_data_ready</code> 执行的正是 <code>wake_up</code> 这条队列——第一课的流水线在套接字层会合。<code>poll/epoll</code> 注册的也是同一条队列，就绪语义天然一致。accept：从监听 sock 的 accept 队列取出已握手的子 sock，为它新造 BSD 套接字与 fd；注意 Linux 上 accept 出来的 fd 不继承监听 fd 的非阻塞标志，<code>accept4</code> 才能一并设定。协议族分岔：<code>AF_UNIX</code>（<a href="/cs/unix-socket">Unix 域套接字</a>）不经网络栈，数据是内核内 skb 拷贝，还能借 SCM_RIGHTS 传 fd；<code>AF_NETLINK</code> 连接内核与用户态的消息口——下一课的 <code>ss</code> 就靠它读内核 sock。</p>',7)),(c(),s(r,null,{default:o(()=>[t(d,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22fd%EF%BC%88%E8%BF%9B%E7%A8%8B%E6%96%87%E4%BB%B6%E8%A1%A8%EF%BC%89%22%5D%20--%3E%20FILE%5B%22file%20%E2%86%92%20sockfs%20%E7%BB%9F%E4%B8%80%E6%93%8D%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20FILE%20--%3E%20BSD%5B%22BSD%20socket%EF%BC%9A%E5%8D%8F%E8%AE%AE%E6%97%8F%E6%97%A0%E5%85%B3%22%5D%0A%20%20BSD%20--%3E%20SOCK%5B%22%E5%8D%8F%E8%AE%AE%20sock%EF%BC%9ATCP%20%2F%20UDP%20%2F%20UNIX%22%5D%0A%20%20SOCK%20--%3E%20Q%5B%22%E6%8E%A5%E6%94%B6%E9%98%9F%E5%88%97%E4%B8%8E%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20RX%5B%22sk_data_ready%22%5D%20--%3E%7C%22wake_up%22%7C%20Q%0A%20%20Q%20--%3E%20WAKE%5B%22%E8%AF%BB%E8%80%85%E9%86%92%E6%9D%A5%EF%BC%8Crecv%20%E5%8F%96%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a('<p><span class="marginnote">数字实例：fd 就是个小整数，从 0 开始编号——shell 起进程时约定 0 是标准输入、1 是标准输出、2 是标准错误，所以 <code>socket()</code> 返回的通常是 3 起。<code>dup(3)</code> 会返回 4，而 3 和 4 在内核里指向同一个 file，引用计数变成 2。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层的机制含义是所有权清晰：fd 是引用，sock 是本体，生命周期跟着最后一个引用走而不是跟第一个 close 走——引用计数到零才触发真正的关闭路径，进入<a href="/cs/npk-tcp-state-machine">上一课</a>的挥手或孤儿状态。等待队列把「生产者在软中断、消费者在进程上下文」的跨上下文会合收成一个原语：任何协议、任何 fd 类型（管道、终端、设备）共享同一套睡眠唤醒合同，这就是为什么 <code>select</code> 能同时等磁盘与网卡。共享同一 sock 的并发读写没有天然隔离，数据竞争要应用自己兜底——套接字层提供原语，不提供策略。</p><p><span class="marginnote">常见误区：初学者容易以为「close 返回，连接就断了」。实际上 close 只是退还一张引用——<code>fork</code> 出的子进程或 <code>dup</code> 出的另一个 fd 还捏着引用时，sock 照活、数据照发，真正的挥手要等最后一张引用退掉才开始。排查「关不掉的连接」时，先数清还有谁攥着这个 fd。</span></p><p><span class="marginnote">直觉类比：sock 像图书馆的一本书，fd 像借书证——可以办好几张证借同一本书。还掉一张证（close 一个 fd），书不会被收回；直到最后一张证也注销（引用计数归零），书才回到关闭流程的柜台上。</span></p><p><span class="marginnote">容量数字：单进程 fd 上限是软限制 <code>RLIMIT_NOFILE</code>（常见默认 1024，服务要显式调高），进程级硬顶 <code>fs.nr_open</code> 默认 1048576，全机总量看 <code>fs.file-max</code>。压测报 EMFILE 时先查这三个数，别先怀疑协议栈。</span></p>',6)),(c(),s(r,null,{default:o(()=>[t(d,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%88%B6%E8%BF%9B%E7%A8%8B%20socket%20%E5%90%8E%20fork%22%5D%20--%3E%20B%5B%22fd%20%E8%A1%A8%E5%90%84%E6%9C%89%E4%B8%80%E4%BB%BD%2C%20file%20%E5%85%B1%E4%BA%AB%22%5D%0A%20%20B%20--%3E%20P%5B%22%E7%88%B6%E8%BF%9B%E7%A8%8B%20close%20%E8%87%AA%E5%B7%B1%E7%9A%84%20fd%22%5D%0A%20%20P%20--%3E%20DEC%5B%22%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%E5%87%8F%E4%B8%80%2C%20%E4%B8%8D%E8%A7%A6%E5%8F%91%E5%85%B3%E9%97%AD%22%5D%0A%20%20DEC%20--%3E%20C%7B%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E8%BF%98%E5%9C%A8%3F%22%7D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20LIVE%5B%22%E8%BF%9E%E6%8E%A5%E7%85%A7%E6%B4%BB%2C%20%E6%95%B0%E6%8D%AE%E7%85%A7%E5%8F%91%22%5D%0A%20%20C%20--%3E%7C%22%E5%AD%90%E8%BF%9B%E7%A8%8B%E4%B9%9F%20close%22%7C%20ZERO%5B%22%E8%AE%A1%E6%95%B0%E5%BD%92%E9%9B%B6%3A%20%E6%89%8D%E8%BF%9B%E5%85%A5%E6%8C%A5%E6%89%8B%2F%E5%AD%A4%E5%84%BF%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重列 Berkeley 调用（<a href="/cs/socket-api">套接字 API</a> 已钉形状），不重讲缓冲会计与非阻塞语义（<a href="/cs/socket-buffers">套接字缓冲与背压</a>、<a href="/cs/socket-nonblock">阻塞与非阻塞套接字</a>），epoll 的惊群与分片在 <a href="/cs/hpc-epoll-deep">epoll 的深化</a>，io_uring 的提交模型不在本课。原始套接字与抓包 socket 留给下一课的工具视角。后课默认：fd 到 sock 的映射与唤醒路径已钉死，内核里的 sock 是可寻址、可查询的对象——下一课的调试工具直接查它们。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fd、BSD 套接字、协议 sock 三层各有分工：进程引用、协议族无关、协议状态。</li><li>阻塞读、poll、epoll 共用 sock 的同一条等待队列，<code>sk_data_ready</code> 是所有就绪事件的生产端。</li><li>生命周期跟 sock 的引用计数走：dup/fork 共享本体，close 只退引用。</li><li>accept 出的 fd 不继承非阻塞标志；<code>AF_UNIX</code> 走内核拷贝还能传 fd，<code>AF_NETLINK</code> 是工具读内核的口。</li><li>出处：Leffler 等, <em>The Design and Implementation of 4.3BSD</em>；Stevens, <em>UNIX Network Programming</em>；Linux sockfs 与 accept(2) 手册口径。</li></ul>',4))])}const F=l(B,[["render",i]]);export{h as __pageData,F as default};
